  <div id="frame"></div>
  <div id="top-meta">EXPLODED ASSEMBLY / ORTHOGRAPHIC PROJECTION</div>
  <div id="figure-number" class="side-caption">FIG_001</div>
  <div id="figure-title" class="side-caption">[ 3.5&quot; FLOPPY DISK ]</div>

  <div id="bottom-ui">
    <div id="explode-prompt">
      <span>PRESS [ SPACE ] TO EXPLODE</span>
    </div>
    <div id="control-hint">LMB: ORBIT · WHEEL: ZOOM · RMB: PAN</div>
  </div>

  <script type="module">
    import * as THREE from "three";
    import { OrbitControls } from "three/addons/controls/OrbitControls.js";
    import {
      CSS2DRenderer,
      CSS2DObject
    } from "three/addons/renderers/CSS2DRenderer.js";

    // -------------------------------------------------------------------------
    // Shared visual and geometric constants
    // -------------------------------------------------------------------------

    const BLUEPRINT_COLOR = 0x4169e1;
    const BLUEPRINT_FILL = 0xeaf0ff;
    const BACKGROUND_COLOR = "#f5f7fa";
    const METAL_COLOR = 0x4a5568;

    const SHELL_WIDTH = 60;
    const SHELL_DEPTH = 60;
    const SHELL_THICKNESS = 1.4;
    const SHELL_CHAMFER = 3;

    const TOTAL_ANIMATION_MS = 3000;
    const STAGGER_MS = 80;
    const PART_COUNT = 8;
    const MAX_STAGGER_MS = STAGGER_MS * (PART_COUNT - 1);
    const PART_MOTION_MS = TOTAL_ANIMATION_MS - MAX_STAGGER_MS;

    /*
     * One shared magnetic-head channel definition.
     *
     * Top shell and bottom shell use these coordinates directly.
     * The shutter is assembled around world Z = HEAD_CHANNEL.z, so its local
     * opening Z becomes zero while retaining the same final world coordinates.
     *
     * widthX = 6 is parallel to the shutter's long X edge.
     * depthZ = 14 is perpendicular to the shutter's long axis.
     */
    const HEAD_CHANNEL = Object.freeze({
      x: -5,
      z: 22,
      widthX: 6,
      depthZ: 14
    });

    const SHUTTER_SIZE = Object.freeze({
      widthX: 22,
      depthZ: 16,
      thicknessY: 0.8
    });

    const SHUTTER_ASSEMBLED = new THREE.Vector3(0, -1.5, HEAD_CHANNEL.z);

    // -------------------------------------------------------------------------
    // DOM and renderer setup
    // -------------------------------------------------------------------------

    const gridCanvas = document.querySelector("#dot-grid");
    const webglContainer = document.querySelector("#webgl-container");
    const labelsContainer = document.querySelector("#labels-container");
    const explodePrompt = document.querySelector("#explode-prompt");

    drawDotGrid();

    const scene = new THREE.Scene();

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setClearColor(0x000000, 0);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    webglContainer.appendChild(renderer.domElement);

    const labelRenderer = new CSS2DRenderer();
    labelRenderer.setSize(window.innerWidth, window.innerHeight);
    labelRenderer.domElement.style.position = "absolute";
    labelRenderer.domElement.style.inset = "0";
    labelRenderer.domElement.style.pointerEvents = "none";
    labelsContainer.appendChild(labelRenderer.domElement);

    const ORTHO_HEIGHT = 135;
    const camera = new THREE.OrthographicCamera();

    camera.position.set(100, 80, 100);
    camera.zoom = 1.08;
    updateCameraFrustum();
    camera.lookAt(0, 0, 0);
    camera.updateProjectionMatrix();

    let controls;

    function setupControls() {
      controls = new OrbitControls(camera, renderer.domElement);

      controls.target.set(0, 0, 0);
      controls.enableDamping = true;
      controls.dampingFactor = 0.075;

      controls.enableRotate = true;
      controls.enableZoom = true;
      controls.enablePan = true;
      controls.screenSpacePanning = true;

      controls.minZoom = 0.65;
      controls.maxZoom = 2.8;

      controls.mouseButtons.LEFT = THREE.MOUSE.ROTATE;
      controls.mouseButtons.MIDDLE = THREE.MOUSE.DOLLY;
      controls.mouseButtons.RIGHT = THREE.MOUSE.PAN;

      renderer.domElement.addEventListener("contextmenu", (event) => {
        event.preventDefault();
      });

      controls.update();
    }

    setupControls();

    // -------------------------------------------------------------------------
    // Blueprint material and geometry helpers
    // -------------------------------------------------------------------------

    function createBlueprintMaterial(
      explodedOpacity = 0.08,
      color = BLUEPRINT_FILL
    ) {
      const material = new THREE.MeshBasicMaterial({
        color,
        side: THREE.DoubleSide,
        transparent: true,
        opacity: 1,
        depthWrite: true
      });

      material.userData.opacityProfile = {
        assembled: 1,
        exploded: explodedOpacity
      };

      return material;
    }

    function createMetalMaterial() {
      const material = new THREE.MeshBasicMaterial({
        color: METAL_COLOR,
        side: THREE.DoubleSide,
        transparent: false,
        opacity: 1,
        depthWrite: true
      });

      material.userData.opacityProfile = {
        assembled: 1,
        exploded: 1
      };

      return material;
    }

    function createEdgeMaterial(opacity = 1) {
      return new THREE.LineBasicMaterial({
        color: BLUEPRINT_COLOR,
        transparent: opacity < 1,
        opacity,
        linewidth: 1.25,
        depthTest: false,
        depthWrite: false
      });
    }

    function addEdgedMesh(
      group,
      geometry,
      {
        position = new THREE.Vector3(),
        rotation = new THREE.Euler(),
        explodedOpacity = 0.08,
        color = BLUEPRINT_FILL,
        metal = false
      } = {}
    ) {
      const material = metal
        ? createMetalMaterial()
        : createBlueprintMaterial(explodedOpacity, color);

      const mesh = new THREE.Mesh(geometry, material);
      mesh.position.copy(position);
      mesh.rotation.copy(rotation);
      mesh.renderOrder = 1;

      const edges = new THREE.LineSegments(
        new THREE.EdgesGeometry(geometry, 20),
        createEdgeMaterial()
      );

      edges.renderOrder = 20;
      mesh.add(edges);
      group.add(mesh);

      return mesh;
    }

    function createExtrudedGeometry(shape, depth, curveSegments = 32) {
      const geometry = new THREE.ExtrudeGeometry(shape, {
        depth,
        bevelEnabled: false,
        curveSegments,
        steps: 1
      });

      // Shape XY becomes world XZ. Extrusion depth becomes centered world Y.
      geometry.rotateX(Math.PI / 2);
      geometry.translate(0, depth / 2, 0);
      geometry.computeVertexNormals();

      return geometry;
    }

    function createChamferedRectangleShape(
      width,
      depth,
      chamfer = SHELL_CHAMFER
    ) {
      const halfWidth = width / 2;
      const halfDepth = depth / 2;
      const shape = new THREE.Shape();

      shape.moveTo(-halfWidth + chamfer, -halfDepth);
      shape.lineTo(halfWidth - chamfer, -halfDepth);
      shape.lineTo(halfWidth, -halfDepth + chamfer);
      shape.lineTo(halfWidth, halfDepth - chamfer);
      shape.lineTo(halfWidth - chamfer, halfDepth);
      shape.lineTo(-halfWidth + chamfer, halfDepth);
      shape.lineTo(-halfWidth, halfDepth - chamfer);
      shape.lineTo(-halfWidth, -halfDepth + chamfer);
      shape.closePath();

      return shape;
    }

    function createRectangleShape(width, depth) {
      const shape = new THREE.Shape();
      const halfWidth = width / 2;
      const halfDepth = depth / 2;

      shape.moveTo(-halfWidth, -halfDepth);
      shape.lineTo(halfWidth, -halfDepth);
      shape.lineTo(halfWidth, halfDepth);
      shape.lineTo(-halfWidth, halfDepth);
      shape.closePath();

      return shape;
    }

    function addRectangleHole(shape, centerX, centerZ, width, depth) {
      const halfWidth = width / 2;
      const halfDepth = depth / 2;
      const hole = new THREE.Path();

      // Clockwise winding for a hole.
      hole.moveTo(centerX - halfWidth, centerZ - halfDepth);
      hole.lineTo(centerX - halfWidth, centerZ + halfDepth);
      hole.lineTo(centerX + halfWidth, centerZ + halfDepth);
      hole.lineTo(centerX + halfWidth, centerZ - halfDepth);
      hole.closePath();

      shape.holes.push(hole);
      return hole;
    }

    function addCircleHole(shape, centerX, centerZ, radius) {
      const hole = new THREE.Path();
      hole.absarc(centerX, centerZ, radius, 0, Math.PI * 2, true);
      shape.holes.push(hole);
      return hole;
    }

    function createHorizontalLine(points, opacity = 1) {
      const geometry = new THREE.BufferGeometry().setFromPoints(points);
      const material = new THREE.LineBasicMaterial({
        color: BLUEPRINT_COLOR,
        transparent: opacity < 1,
        opacity,
        depthTest: false,
        depthWrite: false
      });

      const line = new THREE.Line(geometry, material);
      line.renderOrder = 30;
      return line;
    }

    function createHorizontalSegments(points, opacity = 1) {
      const geometry = new THREE.BufferGeometry().setFromPoints(points);
      const material = new THREE.LineBasicMaterial({
        color: BLUEPRINT_COLOR,
        transparent: opacity < 1,
        opacity,
        depthTest: false,
        depthWrite: false
      });

      const line = new THREE.LineSegments(geometry, material);
      line.renderOrder = 30;
      return line;
    }

    // -------------------------------------------------------------------------
    // TOP SHELL — compound geometry
    // -------------------------------------------------------------------------

    function createTopShell() {
      const group = new THREE.Group();
      group.name = "TOP SHELL";

      const shellShape = createChamferedRectangleShape(
        SHELL_WIDTH,
        SHELL_DEPTH,
        SHELL_CHAMFER
      );

      // (a) HD NOTCH — true square hole.
      addRectangleHole(shellShape, -24, -24, 4, 4);

      // (d) Shared shutter/head channel — true rectangular through-hole.
      addRectangleHole(
        shellShape,
        HEAD_CHANNEL.x,
        HEAD_CHANNEL.z,
        HEAD_CHANNEL.widthX,
        HEAD_CHANNEL.depthZ
      );

      const shellGeometry = createExtrudedGeometry(
        shellShape,
        SHELL_THICKNESS
      );

      addEdgedMesh(group, shellGeometry);

      // (b) Label recess.
      addEdgedMesh(
        group,
        new THREE.BoxGeometry(36, 0.07, 22),
        {
          position: new THREE.Vector3(0, 0.735, -7)
        }
      );

      // Inner inset border inside the label recess.
      addEdgedMesh(
        group,
        new THREE.BoxGeometry(31, 0.035, 17),
        {
          position: new THREE.Vector3(0, 0.756, -7)
        }
      );

      // (c) Shutter sliding recess.
      addEdgedMesh(
        group,
        new THREE.BoxGeometry(20, 0.065, 10),
        {
          position: new THREE.Vector3(0, 0.74, 9)
        }
      );

      // Additional narrow rail guides around the shutter area.
      addEdgedMesh(
        group,
        new THREE.BoxGeometry(1.1, 0.1, 15),
        {
          position: new THREE.Vector3(-10.5, 0.765, 17)
        }
      );

      addEdgedMesh(
        group,
        new THREE.BoxGeometry(1.1, 0.1, 15),
        {
          position: new THREE.Vector3(10.5, 0.765, 17)
        }
      );

      // (e) Direction arrow near the shutter opening.
      const arrowY = 0.82;
      const arrowSegments = createHorizontalSegments([
        new THREE.Vector3(4, arrowY, 16),
        new THREE.Vector3(4, arrowY, 21),

        new THREE.Vector3(4, arrowY, 21),
        new THREE.Vector3(1.8, arrowY, 18.7),

        new THREE.Vector3(4, arrowY, 21),
        new THREE.Vector3(6.2, arrowY, 18.7)
      ]);

      group.add(arrowSegments);

      return group;
    }

    // -------------------------------------------------------------------------
    // DUST LINER — true C contour with a rectangular radial head cutout
    // -------------------------------------------------------------------------

    function createLinerShape(
      outerRadius = 24,
      innerRadius = 15,
      slotLeftX = HEAD_CHANNEL.x - HEAD_CHANNEL.widthX / 2,
      slotRightX = HEAD_CHANNEL.x + HEAD_CHANNEL.widthX / 2
    ) {
      /*
       * Once the rectangular radial slot joins the inner and outer boundaries,
       * the annulus becomes one C-shaped contour. Building it as one contour
       * avoids overlapping Earcut holes while retaining a true cut-through.
       */
      const outerLeftZ = Math.sqrt(
        outerRadius * outerRadius - slotLeftX * slotLeftX
      );
      const outerRightZ = Math.sqrt(
        outerRadius * outerRadius - slotRightX * slotRightX
      );
      const innerLeftZ = Math.sqrt(
        innerRadius * innerRadius - slotLeftX * slotLeftX
      );
      const innerRightZ = Math.sqrt(
        innerRadius * innerRadius - slotRightX * slotRightX
      );

      const outerLeftAngle = Math.atan2(outerLeftZ, slotLeftX);
      const outerRightAngle = Math.atan2(outerRightZ, slotRightX);
      const innerLeftAngle = Math.atan2(innerLeftZ, slotLeftX);
      const innerRightAngle = Math.atan2(innerRightZ, slotRightX);

      const shape = new THREE.Shape();
      const segments = 96;

      shape.moveTo(slotLeftX, outerLeftZ);

      // Long outer arc, excluding only the front rectangular opening.
      const outerEnd = outerRightAngle + Math.PI * 2;

      for (let index = 1; index <= segments; index += 1) {
        const t = index / segments;
        const angle = THREE.MathUtils.lerp(
          outerLeftAngle,
          outerEnd,
          t
        );

        shape.lineTo(
          Math.cos(angle) * outerRadius,
          Math.sin(angle) * outerRadius
        );
      }

      // Right wall of the rectangular cut.
      shape.lineTo(slotRightX, innerRightZ);

      // Long inner arc in reverse.
      const innerEnd = innerLeftAngle - Math.PI * 2;

      for (let index = 1; index <= segments; index += 1) {
        const t = index / segments;
        const angle = THREE.MathUtils.lerp(
          innerRightAngle,
          innerEnd,
          t
        );

        shape.lineTo(
          Math.cos(angle) * innerRadius,
          Math.sin(angle) * innerRadius
        );
      }

      // Left wall of the rectangular cut.
      shape.lineTo(slotLeftX, outerLeftZ);
      shape.closePath();

      return shape;
    }

    function createDustLiner(name) {
      const group = new THREE.Group();
      group.name = name;

      const shape = createLinerShape();
      const geometry = createExtrudedGeometry(shape, 0.13, 48);

      addEdgedMesh(group, geometry, {
        explodedOpacity: 0.08,
        color: 0xdce7ff
      });

      return group;
    }

    // -------------------------------------------------------------------------
    // MAGNETIC DISK — filled disk with track reflections
    // -------------------------------------------------------------------------

    function createMagneticDisk() {
      const group = new THREE.Group();
      group.name = "MAGNETIC DISK";

      const geometry = new THREE.CylinderGeometry(22, 22, 0.3, 96, 1);
      addEdgedMesh(group, geometry, {
        explodedOpacity: 0.5,
        color: 0x7b9df8
      });

      const trackY = 0.18;

      [
        [
          new THREE.Vector3(-15, trackY, -8),
          new THREE.Vector3(-9, trackY, -12)
        ],
        [
          new THREE.Vector3(9, trackY, 12),
          new THREE.Vector3(15, trackY, 8)
        ],
        [
          new THREE.Vector3(12, trackY, -7),
          new THREE.Vector3(17, trackY, -3)
        ]
      ].forEach((points) => {
        group.add(createHorizontalLine(points, 0.85));
      });

      return group;
    }

    // -------------------------------------------------------------------------
    // HUB — extruded metal disk with true circular and square spindle holes
    // -------------------------------------------------------------------------

    function createHub() {
      const group = new THREE.Group();
      group.name = "HUB";

      const shape = new THREE.Shape();
      shape.absarc(0, 0, 5, 0, Math.PI * 2, false);

      // Central circular spindle hole.
      addCircleHole(shape, 0, 0, 1.05);

      // Offset square drive key hole.
      addRectangleHole(shape, 2.55, 0, 1.45, 1.45);

      const geometry = createExtrudedGeometry(shape, 0.42, 64);

      addEdgedMesh(group, geometry, {
        explodedOpacity: 0.08,
        color: 0xcbd8f4
      });

      return group;
    }

    // -------------------------------------------------------------------------
    // BOTTOM SHELL — compound geometry
    // -------------------------------------------------------------------------

    function createBottomShell() {
      const group = new THREE.Group();
      group.name = "BOTTOM SHELL";

      const shellShape = createChamferedRectangleShape(
        SHELL_WIDTH,
        SHELL_DEPTH,
        SHELL_CHAMFER
      );

      // (b) Central spindle opening — true hole.
      addCircleHole(shellShape, 0, 0, 7);

      // (f) Write-protect notch — true square hole.
      addRectangleHole(shellShape, 24, -24, 3, 3);

      // (g) Shared shutter/head opening — true hole.
      addRectangleHole(
        shellShape,
        HEAD_CHANNEL.x,
        HEAD_CHANNEL.z,
        HEAD_CHANNEL.widthX,
        HEAD_CHANNEL.depthZ
      );

      const shellGeometry = createExtrudedGeometry(
        shellShape,
        SHELL_THICKNESS
      );

      addEdgedMesh(group, shellGeometry);

      // (a) Central circular disk recess, preserving the central hole.
      const recessShape = new THREE.Shape();
      recessShape.absarc(0, 0, 22, 0, Math.PI * 2, false);
      addCircleHole(recessShape, 0, 0, 7);

      addEdgedMesh(
        group,
        createExtrudedGeometry(recessShape, 0.065, 64),
        {
          position: new THREE.Vector3(0, 0.73, 0)
        }
      );

      // Secondary guide ring.
      const guideShape = new THREE.Shape();
      guideShape.absarc(0, 0, 18, 0, Math.PI * 2, false);
      addCircleHole(guideShape, 0, 0, 17.55);

      addEdgedMesh(
        group,
        createExtrudedGeometry(guideShape, 0.055, 64),
        {
          position: new THREE.Vector3(0, 0.775, 0)
        }
      );

      // (c) Four corner locating posts.
      [
        [-23.5, -23.5],
        [23.5, -23.5],
        [-23.5, 23.5],
        [23.5, 23.5]
      ].forEach(([x, z]) => {
        addEdgedMesh(
          group,
          new THREE.CylinderGeometry(1.5, 1.5, 1, 24),
          {
            position: new THREE.Vector3(x, 1.18, z)
          }
        );
      });

      // (d) LIFTER.
      addEdgedMesh(
        group,
        new THREE.BoxGeometry(8, 1, 4),
        {
          position: new THREE.Vector3(0, 1.18, 11)
        }
      );

      // (e) SHUTTER SPRING recess.
      addEdgedMesh(
        group,
        new THREE.BoxGeometry(10, 0.07, 4),
        {
          position: new THREE.Vector3(8.5, 0.735, 24)
        }
      );

      // Small spring guide block.
      addEdgedMesh(
        group,
        new THREE.BoxGeometry(2, 0.65, 2.5),
        {
          position: new THREE.Vector3(14.5, 1.02, 24)
        }
      );

      return group;
    }

    // -------------------------------------------------------------------------
    // SHUTTER — opaque compound metal plate with a true offset opening
    // -------------------------------------------------------------------------

    function createShutter() {
      const group = new THREE.Group();
      group.name = "SHUTTER";

      const shape = createRectangleShape(
        SHUTTER_SIZE.widthX,
        SHUTTER_SIZE.depthZ
      );

      const localHoleX = HEAD_CHANNEL.x - SHUTTER_ASSEMBLED.x;
      const localHoleZ = HEAD_CHANNEL.z - SHUTTER_ASSEMBLED.z;

      /*
       * True offset window:
       * - X width 6 is parallel to the plate's long X edge.
       * - Z depth 14 is perpendicular to the plate's long axis.
       * - X = -5 places it on the left side rather than at the center.
       */
      addRectangleHole(
        shape,
        localHoleX,
        localHoleZ,
        HEAD_CHANNEL.widthX,
        HEAD_CHANNEL.depthZ
      );

      addEdgedMesh(
        group,
        createExtrudedGeometry(shape, SHUTTER_SIZE.thicknessY),
        { metal: true }
      );

      // Raised side wraps create the recognizable shallow U-profile.
      addEdgedMesh(
        group,
        new THREE.BoxGeometry(0.75, 1.25, SHUTTER_SIZE.depthZ),
        {
          position: new THREE.Vector3(
            -SHUTTER_SIZE.widthX / 2 + 0.25,
            0,
            0
          ),
          metal: true
        }
      );

      addEdgedMesh(
        group,
        new THREE.BoxGeometry(0.75, 1.25, SHUTTER_SIZE.depthZ),
        {
          position: new THREE.Vector3(
            SHUTTER_SIZE.widthX / 2 - 0.25,
            0,
            0
          ),
          metal: true
        }
      );

      return group;
    }

    function createWriteProtectTab() {
      const group = new THREE.Group();
      group.name = "WRITE PROTECT TAB";

      addEdgedMesh(
        group,
        new THREE.BoxGeometry(3, 2, 3),
        {
          explodedOpacity: 0.08,
          color: 0xd6e2ff
        }
      );

      return group;
    }

    // -------------------------------------------------------------------------
    // Build scene components
    // -------------------------------------------------------------------------

    const topShell = createTopShell();
    const upperLiner = createDustLiner("DUST LINER UPPER");
    const magneticDisk = createMagneticDisk();
    const hub = createHub();
    const lowerLiner = createDustLiner("DUST LINER LOWER");
    const bottomShell = createBottomShell();
    const shutter = createShutter();
    const writeProtectTab = createWriteProtectTab();

    scene.add(
      bottomShell,
      lowerLiner,
      magneticDisk,
      hub,
      upperLiner,
      topShell,
      shutter,
      writeProtectTab
    );

    // -------------------------------------------------------------------------
    // === ANIMATION: part setup ===
    // -------------------------------------------------------------------------

    let parts = [];

    function collectOpacityMaterials(group) {
      const materials = new Set();

      group.traverse((object) => {
        if (!object.isMesh) {
          return;
        }

        const objectMaterials = Array.isArray(object.material)
          ? object.material
          : [object.material];

        objectMaterials.forEach((material) => {
          if (material?.userData?.opacityProfile) {
            materials.add(material);
          }
        });
      });

      return [...materials];
    }

    function setupParts() {
      const definitions = [
        {
          group: topShell,
          assembled: new THREE.Vector3(0, 1.5, 0),
          exploded: new THREE.Vector3(0, 45, 0),
          delay: STAGGER_MS * 0
        },
        {
          group: upperLiner,
          assembled: new THREE.Vector3(0, 1.0, 0),
          exploded: new THREE.Vector3(0, 30, 0),
          delay: STAGGER_MS * 1
        },
        {
          group: magneticDisk,
          assembled: new THREE.Vector3(0, 0.5, 0),
          exploded: new THREE.Vector3(0, 15, 0),
          delay: STAGGER_MS * 2
        },
        {
          group: hub,
          assembled: new THREE.Vector3(0, 0.7, 0),
          exploded: new THREE.Vector3(0, 18, 0),
          delay: STAGGER_MS * 3
        },
        {
          group: lowerLiner,
          assembled: new THREE.Vector3(0, 0, 0),
          exploded: new THREE.Vector3(0, 0, 0),
          delay: STAGGER_MS * 4
        },
        {
          group: bottomShell,
          assembled: new THREE.Vector3(0, -1.5, 0),
          exploded: new THREE.Vector3(0, -15, 0),
          delay: STAGGER_MS * 5
        },
        {
          group: shutter,
          assembled: SHUTTER_ASSEMBLED.clone(),
          exploded: new THREE.Vector3(-42, -15, 34),
          delay: STAGGER_MS * 6
        },
        {
          group: writeProtectTab,
          assembled: new THREE.Vector3(24, -1, -24),
          exploded: new THREE.Vector3(44, -15, -38),
          delay: STAGGER_MS * 7
        }
      ];

      parts = definitions.map((definition) => {
        definition.group.position.copy(definition.assembled);

        return {
          ...definition,
          materials: collectOpacityMaterials(definition.group)
        };
      });

      applyEndpointState(false);
    }

    function applyEndpointState(exploded) {
      parts.forEach((part) => {
        part.group.position.copy(
          exploded ? part.exploded : part.assembled
        );

        part.materials.forEach((material) => {
          const profile = material.userData.opacityProfile;
          material.opacity = exploded
            ? profile.exploded
            : profile.assembled;

          material.depthWrite =
            material.opacity > 0.98 || profile.exploded === 1;
        });
      });
    }

    setupParts();

    // -------------------------------------------------------------------------
    // Dashed assembly projection lines
    // -------------------------------------------------------------------------

    const connectorLines = [];

    function createDashedConnector(points) {
      const geometry = new THREE.BufferGeometry().setFromPoints(points);

      const material = new THREE.LineDashedMaterial({
        color: BLUEPRINT_COLOR,
        transparent: true,
        opacity: 0,
        dashSize: 1.5,
        gapSize: 1.05,
        depthTest: false,
        depthWrite: false
      });

      const line = new THREE.Line(geometry, material);
      line.computeLineDistances();
      line.visible = false;
      line.renderOrder = 25;

      scene.add(line);
      connectorLines.push(line);

      return line;
    }

    function setupConnectors() {
      [
        [-27, -27],
        [27, -27],
        [-27, 27],
        [27, 27]
      ].forEach(([x, z]) => {
        createDashedConnector([
          new THREE.Vector3(x, -15, z),
          new THREE.Vector3(x, 45, z)
        ]);
      });

      // Shutter diagonal connection.
      createDashedConnector([
        new THREE.Vector3(-10, -14.3, 24),
        new THREE.Vector3(-42, -14.3, 34)
      ]);

      // Write-protect tab diagonal connection.
      createDashedConnector([
        new THREE.Vector3(24, -14.3, -24),
        new THREE.Vector3(44, -14.3, -38)
      ]);
    }

    setupConnectors();

    // -------------------------------------------------------------------------
    // CSS2D annotations and leader lines
    // -------------------------------------------------------------------------

    const annotations = [];

    function createAnnotation(text, anchor, labelPosition) {
      const element = document.createElement("div");
      element.className = "part-label";
      element.textContent = text;
      element.style.opacity = "0";

      const label = new CSS2DObject(element);
      label.position.copy(labelPosition);
      label.visible = false;
      scene.add(label);

      const leaderGeometry = new THREE.BufferGeometry().setFromPoints([
        anchor,
        labelPosition
      ]);

      const leaderMaterial = new THREE.LineBasicMaterial({
        color: BLUEPRINT_COLOR,
        transparent: true,
        opacity: 0,
        depthTest: false,
        depthWrite: false
      });

      const leader = new THREE.Line(leaderGeometry, leaderMaterial);
      leader.visible = false;
      leader.renderOrder = 28;
      scene.add(leader);

      annotations.push({
        element,
        label,
        leader,
        anchor,
        labelPosition
      });
    }

    function setupAnnotations() {
      createAnnotation(
        "HD NOTCH",
        new THREE.Vector3(-24, 45.8, -24),
        new THREE.Vector3(-39, 50, -29)
      );

      createAnnotation(
        "TOP SHELL",
        new THREE.Vector3(27, 45.2, 3),
        new THREE.Vector3(41, 48, 3)
      );

      createAnnotation(
